// The TypeScript port must produce exactly what the Rails code produces for the shared
// synthetic fixtures. expected/*.json is generated by Ruby (see fixtures/README.md).
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { Categorizer, ImportError, merchantKey, parseStatement, titleizeMerchant, decimalToCents } from "../src";

const fixtures = join(__dirname, "../fixtures");
const json = (path: string) => JSON.parse(readFileSync(join(fixtures, path), "utf8"));

describe("Ruby parity: categorizer", () => {
  const cases: Array<{ description: string; amount: string; merchant_key: string | null; merchant_title: string | null; category: string }> = json("expected/categorize.json");

  it.each(cases)("$description", (item) => {
    expect(merchantKey(item.description)).toBe(item.merchant_key);
    expect(titleizeMerchant(merchantKey(item.description))).toBe(item.merchant_title);
    expect(new Categorizer().categorize(item.description, decimalToCents(item.amount))).toBe(item.category);
  });

  it("covers every input case", () => {
    expect(cases.length).toBe(json("categorize-cases.json").length);
  });
});

describe("Ruby parity: statement parsing", () => {
  const files = readdirSync(join(fixtures, "statements")).filter((name) => name.endsWith(".csv"));

  it.each(files)("%s", (file) => {
    const text = readFileSync(join(fixtures, "statements", file), "utf8").replace(/^﻿/, "");
    const parsed = parseStatement(text, { filename: file, currency: "USD", categorizer: new Categorizer() });
    expect(parsed).toEqual(json(`expected/${file.replace(/\.csv$/, ".json")}`));
  });

  const errors: Array<{ name: string; csv: string; code: string | null; row?: number }> = json("statements/errors.json");
  const rubyCodes: Record<string, string | null> = Object.fromEntries(json("expected/errors.json").map((e: { name: string; code: string | null }) => [e.name, e.code]));

  it.each(errors)("rejects: $name", (item) => {
    expect(rubyCodes[item.name]).toBe(item.code); // the fixture agrees with Ruby
    const parse = () => parseStatement(item.csv, { filename: "x.csv", currency: "USD", categorizer: new Categorizer() });
    if (item.code === null) {
      expect(parse).not.toThrow();
      return;
    }
    let caught: unknown;
    try {
      parseStatement(item.csv, { filename: "x.csv", currency: "USD", categorizer: new Categorizer() });
    } catch (error) {
      caught = error;
    }
    expect(caught).toBeInstanceOf(ImportError);
    expect((caught as ImportError).code).toBe(item.code);
    if (item.row) expect((caught as ImportError).row).toBe(item.row);
  });
});
